def smallestDivisor(nums: list[int], threshold: int) -> int:
    import math
    lo, hi = 1, max(nums)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        total = sum(math.ceil(x / mid) for x in nums)
        if total <= threshold:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

